INSERT INTO `combos` VALUES (1,'Combo Solo','1 bắp rang bơ (L) + 1 nước ngọt (L)',85000,NULL,1,'2026-10-28 11:14:28','2026-10-28 11:14:28'),(2,'Combo Couple','1 bắp rang bơ (L) + 2 nước ngọt (L)',115000,NULL,1,'2026-10-28 11:14:28','2026-10-28 11:14:28'),(3,'Combo Gia đình','2 bắp rang bơ (L) + 4 nước ngọt (L) + 1 snack',219000,NULL,1,'2026-10-28 11:14:28','2026-10-28 11:14:28'),(4,'Bắp rang bơ (L)','Vị bơ hoặc caramel',59000,NULL,1,'2026-10-28 11:14:28','2026-10-28 11:14:28'),(5,'Nước ngọt (L)','Nước ngọt có ga các loại, 32oz',35000,NULL,1,'2026-10-28 11:14:28','2026-10-28 11:14:28'),(6,'Combo Halloween','Bắp phô mai + 2 nước + ly hình bí ngô (đã hết hàng)',149000,NULL,0,'2026-10-28 11:14:28','2026-10-28 11:14:28');
